CustomField.formula:
/* Time spent in Unqualified */

/* WEEKS */
IF(
    FLOOR(Time_spent_in_Unqualified__c / 10080) > 0,
    TEXT(FLOOR(Time_spent_in_Unqualified__c / 10080)) &
    IF(FLOOR(Time_spent_in_Unqualified__c / 10080) = 1, " Week ", " Weeks "),
    ""
) &

/* DAYS */
IF(
    FLOOR(MOD(Time_spent_in_Unqualified__c, 10080) / 1440) > 0,
    TEXT(FLOOR(MOD(Time_spent_in_Unqualified__c, 10080) / 1440)) &
    IF(FLOOR(MOD(Time_spent_in_Unqualified__c, 10080) / 1440) = 1, " Day ", " Days "),
    ""
) &

/* HOURS */
IF(
    FLOOR(MOD(Time_spent_in_Unqualified__c, 1440) / 60) > 0,
    TEXT(FLOOR(MOD(Time_spent_in_Unqualified__c, 1440) / 60)) &
    IF(FLOOR(MOD(Time_spent_in_Unqualified__c, 1440) / 60) = 1, " Hour ", " Hours "),
    ""
) &

/* MINUTES — no decimals */
IF(
    ROUND(MOD(Time_spent_in_Unqualified__c, 60), 0) > 0,
    TEXT(ROUND(MOD(Time_spent_in_Unqualified__c, 60), 0)) &
    IF(ROUND(MOD(Time_spent_in_Unqualified__c, 60), 0) = 1, " Minute", " Minutes"),
    ""
)
